    // =========================================================
    // НОРМАЛИЗАЦИЯ
    // =========================================================

    function normalize(text) {

        return String(text || '')
            .toLowerCase()
            .replace(/ё/g, 'е')
            .replace(/[—–−]/g, '-')
            .replace(/\s+/g, ' ')
            .trim();

    }


    // =========================================================
    // ПОИСК РЕГИОНА
    // =========================================================

    function findRegion(text) {

        const value = normalize(text);

        if (!value) {
            return null;
        }

        for (const region of REGIONS) {

            const variants = [
                region.name,
                ...(region.aliases || [])
            ];

            for (const variant of variants) {

                const normalized =
                    normalize(variant);

                if (
                    value === normalized ||
                    value.includes(normalized) ||
                    normalized.includes(value)
                ) {
                    return region;
                }

            }

        }

        return null;
    }



